// Pokémon Mutagen: the lockup in the menu bar. wordmark-path.js (generated by tools/brand/brand.py)
// provides the paths; this swaps the book's title text for the mark and the wordmark, linked home.
(function () {
  var data = window.MUTAGEN;
  var title = document.querySelector(".menu-title");
  if (!data || !title) return;
  var script = document.querySelector('script[src$="pokerom/brand/mutagen.js"]');
  var root = script ? script.getAttribute("src").replace(/pokerom\/brand\/mutagen\.js$/, "") : "";
  var ns = "http://www.w3.org/2000/svg";
  function icon(cls, w, h, parts) {
    var svg = document.createElementNS(ns, "svg");
    svg.setAttribute("viewBox", "0 0 " + w + " " + h);
    svg.setAttribute("shape-rendering", "crispEdges");
    svg.setAttribute("aria-hidden", "true");
    svg.setAttribute("class", cls);
    parts.forEach(function (part) {
      var path = document.createElementNS(ns, "path");
      path.setAttribute("fill", part[0]);
      path.setAttribute("d", part[1]);
      svg.appendChild(path);
    });
    return svg;
  }
  var link = document.createElement("a");
  link.href = root + "index.html";
  link.setAttribute("aria-label", "Pokémon Mutagen, home");
  link.appendChild(icon("mark", data.mark.w, data.mark.h, [["currentColor", data.mark.upper], ["#C43AD6", data.mark.lower]]));
  var eyebrow = document.createElement("span");
  eyebrow.className = "eyebrow";
  eyebrow.textContent = "POKÉMON";
  link.appendChild(eyebrow);
  link.appendChild(icon("wordmark", data.wordmark.w, data.wordmark.h, [["currentColor", data.wordmark.d]]));
  title.textContent = "";
  title.appendChild(link);
})();
